terraform {
  backend "s3" {}
}
provider "aws" {
  allowed_account_ids = ["111111111111"]
}
resource "aws_iam_role" "r" {
  name               = "r"
  assume_role_policy = "{}"
  permissions_boundary = aws_iam_policy.b.arn
}
resource "aws_sfn_state_machine" "sm" {
  name       = "orders"
  role_arn   = "x"
  definition = "{}"
}
resource "aws_iam_role_policy" "p" {
  role   = aws_iam_role.r.name
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = ["sqs:SendMessage"], Resource = "*" }] })
}
resource "aws_kms_key" "k" {
  policy = jsonencode({ Statement = [{ Effect = "Allow", NotPrincipal = { AWS = [aws_iam_role.r.arn, "arn:aws:iam::111111111111:root"] }, Action = "kms:*", Resource = "*" }] })
}
resource "aws_sqs_queue" "jobs" {
  name              = "jobs"
  kms_master_key_id = aws_kms_key.k.arn
}
resource "aws_lambda_function" "f" {
  function_name = "f"
  role          = aws_iam_role.r.arn
  environment {
    variables = { JOBS_QUEUE_URL = aws_sqs_queue.jobs.url }
  }
}
resource "aws_iam_policy" "b" {
  name   = "b"
  policy = jsonencode({ Statement = [{ Effect = "Allow", Action = "*", Resource = "*" }] })
}

terraform {
  backend "s3" {}
}
